	@Test
	void scopedScalarRetentionCopiesRawBindingsBeforeShortCircuit() {
		try (ScopedEvaluationOwner owner = ScopedEvaluationOwner.root(EmptyBindingSet.getInstance())) {
			ScopedEvaluationProbe.Context context = new ScopedEvaluationProbe.Context(owner, Set.of("missing"),
					Set.of());
			QueryBindingSet raw = new QueryBindingSet();
			raw.addBinding("known", ONE);
			ProbeBindingSet input = ProbeBindingSet.of(context,
					new ScopedEvaluationProbe.Row(raw, Set.of("known")));
			AtomicReference<BindingSet> captured = new AtomicReference<>();
			DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), service -> {
				throw new QueryEvaluationException("service lookup is not part of this scalar test");
			});
			QueryValueEvaluationStep preparedIf = strategy.precompile(
					new If(new ValueConstant(BooleanLiteral.TRUE), new ValueConstant(BooleanLiteral.TRUE),
							new Bound(Var.of("missing"))),
					new QueryEvaluationContext.Minimal((Dataset) null));
			QueryValueEvaluationStep condition = bindings -> {
				captured.set(bindings);
				return preparedIf.evaluate(bindings);
			};

			Value result = new ScopedQueryValueEvaluationStep(Set.of("known", "missing"), condition)
					.evaluate(input);

			assertEquals(BooleanLiteral.TRUE, result);
			assertEquals(ONE, captured.get().getValue("known"));
			assertThrows(ProbeBlocked.class, () -> captured.get().getValue("missing"));
		}
	}

