	private static List<BindingSet> evaluate(TupleExpr expression,
			Map<String, RecordingFederatedService> services) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(),
				services::get);
		QueryEvaluationStep prepared = strategy.precompile(expression);
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = prepared.evaluate(EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				rows.add(iteration.next());
			}
		}
		return rows;
	}

	private static Map<String, RecordingFederatedService> services(RecordingFederatedService c,
			RecordingFederatedService d, RecordingFederatedService y) {
		return Map.of("urn:test:c", c, "urn:test:d", d, "urn:test:y", y);
	}

	private static BindingSetAssignment emptyValuesDeclaring(String name) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of(name));
		assignment.setBindingSets(List.of());
		return assignment;
	}

	private static BindingSetAssignment values(boolean includeUndefinedX) {
		BindingSet row = includeUndefinedX
				? new ListBindingSet(List.of("x", "y"), Arrays.asList((Value) null, ONE))
				: new ListBindingSet(List.of("y"), ONE);
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(includeUndefinedX ? Set.of("x", "y") : Set.of("y"));
		assignment.setBindingSets(List.of(row));
		return assignment;
	}

	private static Service service(String endpoint, String subject, String predicate, String object) {
		return new Service(Var.of("serviceRef", VF.createIRI(endpoint)),
				new StatementPattern(Var.of(subject),
						Var.of(predicate, VF.createIRI("urn:test:" + predicate), false, true),
						Var.of(object)),
				"{ ?" + subject + " <urn:test:" + predicate + "> ?" + object + " }", Map.of(), null, false);
	}

	private static QueryBindingSet serviceRow(String name, Value value, String secondName) {
		QueryBindingSet row = new QueryBindingSet();
		row.addBinding(name, value);
		row.addBinding(secondName, VF.createIRI("urn:test:value"));
		return row;
	}

	private static final class RecordingFederatedService implements FederatedService {
		private final List<BindingSet> rows;
		private final AtomicInteger invocationCount = new AtomicInteger();
		private final List<BindingSet> requestBindings = new ArrayList<>();

		private RecordingFederatedService(List<BindingSet> rows) {
			this.rows = List.copyOf(rows);
		}

		private int invocationCount() {
			return invocationCount.get();
		}

		private List<BindingSet> requestBindings() {
			return requestBindings;
		}

		@Override
		public boolean ask(Service service, BindingSet bindings, String baseUri) {
			record(bindings);
			return !matchingRows(bindings).isEmpty();
		}

		@Override
		public CloseableIteration<BindingSet> select(Service service, Set<String> projectionVars,
				BindingSet bindings, String baseUri) {
			record(bindings);
			return new CloseableIteratorIteration<>(matchingRows(bindings).iterator());
		}

		@Override
		public CloseableIteration<BindingSet> evaluate(Service service, CloseableIteration<BindingSet> bindings,
				String baseUri) {
			List<BindingSet> inputMappings = new ArrayList<>();
			try (bindings) {
				while (bindings.hasNext()) {
					inputMappings.add(snapshot(bindings.next()));
				}
			}
			if (inputMappings.isEmpty()) {
				return new EmptyIteration<>();
			}

			invocationCount.incrementAndGet();
			requestBindings.addAll(inputMappings);
			List<BindingSet> results = new ArrayList<>();
			for (BindingSet input : inputMappings) {
				results.addAll(matchingRows(input));
			}
			return new CloseableIteratorIteration<>(results.iterator());
		}

		@Override
		public boolean isInitialized() {
			return true;
		}

		@Override
		public void initialize() throws QueryEvaluationException {
		}

		@Override
		public void shutdown() throws QueryEvaluationException {
		}

		private void record(BindingSet bindings) {
			invocationCount.incrementAndGet();
			requestBindings.add(snapshot(bindings));
		}

		private static BindingSet snapshot(BindingSet bindings) {
			return new QueryBindingSet(bindings);
		}

		private List<BindingSet> matchingRows(BindingSet input) {
			List<BindingSet> results = new ArrayList<>();
			for (BindingSet row : rows) {
				if (!input.isCompatible(row)) {
					continue;
				}
				QueryBindingSet merged = new QueryBindingSet(input);
				for (Binding binding : row) {
					merged.setBinding(binding.getName(), binding.getValue());
				}
				results.add(merged);
			}
			return results;
		}
	}
